def compact_if_needed(admin: SegmentAdmin, seg_id: str, max_ratio: float = 0.20) -> bool:
    if admin.tombstone_ratio(seg_id) <= max_ratio:
        return False
    new_seg = None
    for attempt in range(3):
        try:
            new_seg = admin.build_clean_segment(seg_id)
            if admin.measure_recall(new_seg) < 0.95:
                admin.drop_segment(new_seg)
                raise RuntimeError(f'Recall gate failed for {new_seg}; rolled back')
            admin.atomic_swap(seg_id, new_seg)
            return True
        except OSError as exc:
            if new_seg:
                admin.drop_segment(new_seg)
            if attempt == 2:
                raise RuntimeError(f'Compaction failed for {seg_id}: {exc}') from exc
            time.sleep((0.5 * (2 ** attempt)) + random.uniform(0, 0.2))
    return False
